//! E2 of ADR-0046: the time-major acceptance. A day of Tenants arriving,
//! their Devices managed over the following hours and telling facts on a
//! gapless stream, a publication per Tenant and the facts of applying it —
//! written as a Plan over faker, generated by the engine through spills, and
//! validated. The arrivals are a Poisson process (dispersion about 1 by
//! chunk), the total exact when it is fixed; `apportion` and a key drawn from
//! time are the negative controls.

mod fixture;

use std::collections::BTreeMap;
use std::io::Cursor;

use ascetic_ddd_command_log::Reader;
use ascetic_ddd_command_log::engine::{Config, EngineError, Unit, generate};
use ascetic_ddd_command_log::record::{Action, Header, On, Record, StepId};
use ascetic_ddd_command_log::validate::{Limits, NoHost, validate};
use ascetic_ddd_faker::apportion::apportion;
use ascetic_ddd_faker::law::{Categorical, Law, Poisson};
use ascetic_ddd_faker::testing::chi_square;
use ascetic_ddd_faker::{Key, Seed};
use fixture::*;

const HOUR: u64 = 3_600_000_000;
const DAY: u64 = 24 * HOUR;
const CHUNKS: u64 = 96;

#[derive(Clone, Copy, PartialEq)]
enum Arrivals {
    /// Each Tenant's arrival uniform over the day, from its key.
    Uniform,
    /// The negative control: so many a chunk by `apportion`, evenly placed.
    Apportioned,
}

#[derive(Clone, Copy, PartialEq)]
enum Attributes {
    /// A Device's OS from its identity's key.
    Identity,
    /// The negative control: from a key of its arrival time.
    Time,
}

#[derive(Clone, Copy)]
struct Day {
    tenants: u64,
    day: u64,
    arrivals: Arrivals,
    attributes: Attributes,
}

fn root() -> Key {
    Key::root(Seed(2026)).child("acceptance")
}

impl Day {
    fn arrival(&self, t: u64) -> u64 {
        match self.arrivals {
            Arrivals::Uniform => {
                root().child("tenant").at(t).child("arrival").unit().raw() % self.day
            }
            Arrivals::Apportioned => {
                let weights = Categorical::from_counts(&vec![1; CHUNKS as usize]).unwrap();
                let split = apportion(self.tenants, weights, root().child("split").unit());
                // The tenant's chunk: the one its rank falls in.
                let mut before = 0;
                let chunk = split
                    .counts()
                    .position(|c| {
                        before += c;
                        t < before
                    })
                    .unwrap() as u64;
                let width = self.day / CHUNKS;
                chunk * width + root().child("tenant").at(t).child("inside").unit().raw() % width
            }
        }
    }
}

/// One Tenant: its unit of identity.
struct Tenant {
    plan: Day,
    t: u64,
}

impl Unit for Tenant {
    fn emit(
        &self,
        out: &mut dyn FnMut(Record) -> Result<(), EngineError>,
    ) -> Result<(), EngineError> {
        let t = self.t;
        let key = root().child("tenant").at(t);
        let arrived = self.plan.arrival(t);
        let onboarded = step(id("tenant", t, "onboarded", 0), arrived);
        let published = after(
            step(id("tenant", t, "published", 0), arrived + 3 * HOUR),
            &onboarded.step,
            On::Expected,
        );
        let devices = Poisson::new(3.0)
            .unwrap()
            .quantile(key.child("devices").unit());
        let os = Categorical::from_weights(&[0.7, 0.25, 0.05]).unwrap();
        for d in 0..devices {
            let device = t * 1_000 + d;
            let dkey = key.child("device").at(d);
            let at = arrived + 1 + dkey.child("managed").unit().raw() % (6 * HOUR);
            let attribute = match self.plan.attributes {
                Attributes::Identity => os.quantile(dkey.child("os").unit()),
                Attributes::Time => os.quantile(root().child("at").at(at).unit()),
            };
            let mut managed = after(
                step(id("device", device, "managed", 0), at),
                &onboarded.step,
                On::Expected,
            );
            managed = with_payload(
                managed,
                ascetic_ddd_command_log::record::Codec::Text,
                attribute as usize + 1,
                vec![],
            );
            let mut before = managed.step.clone();
            let mut when = at;
            for n in 0..3u32 {
                when += HOUR + dkey.child("fact").at(u64::from(n)).unit().raw() % 60_000_000;
                let fact = message(
                    step(id("device", device, "fact", n), when),
                    "lifecycle",
                    n + 1,
                );
                let fact = after(fact, &before, On::Expected);
                before = fact.step.clone();
                out(fact)?;
            }
            if at < published.at {
                let applied = step(id("device", device, "applied", 0), published.at + 1 + d);
                let applied = after(
                    after(applied, &published.step, On::Expected),
                    &managed.step,
                    On::Expected,
                );
                out(applied)?;
            }
            out(managed)?;
        }
        out(published)?;
        out(onboarded)
    }
}

fn header_for_a_day() -> Header {
    let mut h = header();
    h.window = 12 * HOUR;
    h.retained = vec!["onboarded".into()];
    h
}

fn run(plan: Day, threads: usize) -> Vec<Record> {
    let dir = tempfile::tempdir().unwrap();
    let tenants: Vec<Tenant> = (0..plan.tenants).map(|t| Tenant { plan, t }).collect();
    let units: Vec<&dyn Unit> = tenants.iter().map(|u| u as &dyn Unit).collect();
    let config = Config {
        threads,
        budget: 1 << 20,
        cell: HOUR,
        cells: 48,
        spill: dir.path().to_owned(),
    };
    let (bytes, trailer) = generate(header_for_a_day(), &units, &config, Vec::new()).unwrap();
    let report = validate(
        Reader::new(Cursor::new(&bytes)).unwrap(),
        &NoHost,
        &Limits::new(dir.path()),
    )
    .unwrap();
    assert!(
        report.violations.is_empty(),
        "{:?}",
        &report.violations[..report.violations.len().min(5)]
    );
    assert_eq!(report.records, trailer.records);
    Reader::new(Cursor::new(bytes))
        .unwrap()
        .map(Result::unwrap)
        .collect()
}

/// Onboardings a chunk of the day.
fn by_chunk(records: &[Record], day: u64) -> Vec<u64> {
    let mut counts = vec![0u64; CHUNKS as usize];
    for r in records.iter().filter(|r| r.step.label == "onboarded") {
        counts[(r.at / (day / CHUNKS)) as usize] += 1;
    }
    counts
}

/// The chunks' counts against their mean: a Poisson process gives a p-value
/// well inside (0, 1); counts too even give one near 1.
fn dispersion(counts: &[u64]) -> f64 {
    let mean = counts.iter().sum::<u64>() as f64 / counts.len() as f64;
    chi_square(counts, &vec![mean; counts.len()])
        .unwrap()
        .p_value
}

/// E2: an open total — the Tenants' number a Poisson draw — and their arrivals
/// a Poisson process over the day: dispersion about 1 by chunk; the log
/// validates.
#[test]
fn a_day_of_arrivals_is_a_poisson_process() {
    let tenants = Poisson::new(1_500.0)
        .unwrap()
        .quantile(root().child("tenants").unit());
    let plan = Day {
        tenants,
        day: DAY,
        arrivals: Arrivals::Uniform,
        attributes: Attributes::Identity,
    };
    println!("open total: {tenants} Tenants drawn");
    let records = run(plan, 3);
    let counts = by_chunk(&records, DAY);
    assert_eq!(counts.iter().sum::<u64>(), tenants);
    let p = dispersion(&counts);
    println!("dispersion p = {p}");
    assert!((0.001..0.999).contains(&p), "p = {p}");
    // Every kind of step is there.
    for label in ["onboarded", "published", "managed", "fact", "applied"] {
        assert!(records.iter().any(|r| r.step.label == label), "{label}");
    }
}

/// E2: a fixed total is exact, and spread as a Poisson process's is; the
/// negative control, so many a chunk by `apportion`, is too even and refused.
#[test]
fn a_fixed_total_is_exact_and_apportion_is_refused() {
    let plan = Day {
        tenants: 1_200,
        day: DAY,
        arrivals: Arrivals::Uniform,
        attributes: Attributes::Identity,
    };
    let counts = by_chunk(&run(plan, 2), DAY);
    assert_eq!(counts.iter().sum::<u64>(), 1_200);
    let p = dispersion(&counts);
    println!("dispersion p = {p}");
    assert!((0.001..0.999).contains(&p), "p = {p}");

    let even = Day {
        arrivals: Arrivals::Apportioned,
        ..plan
    };
    let counts = by_chunk(&run(even, 2), DAY);
    assert_eq!(counts.iter().sum::<u64>(), 1_200);
    let p = dispersion(&counts);
    println!("dispersion p = {p}");
    assert!(
        p > 0.999,
        "apportion's counts pass as a Poisson process's: p = {p}"
    );
}

fn attributes(records: &[Record]) -> BTreeMap<StepId, Vec<u8>> {
    records
        .iter()
        .filter(|r| r.step.label == "managed")
        .filter_map(|r| match &r.action {
            Action::Host(h) => Some((r.step.clone(), h.args.bytes.clone())),
            _ => None,
        })
        .collect()
}

/// E2: common random numbers. A Device's attributes are its identity's: a day
/// half as long moves every arrival and changes none of them. The negative
/// control draws them from a key of time, and they change.
#[test]
fn attributes_do_not_move_with_time() {
    let plan = Day {
        tenants: 300,
        day: DAY,
        arrivals: Arrivals::Uniform,
        attributes: Attributes::Identity,
    };
    let shorter = Day {
        day: DAY / 2,
        ..plan
    };
    let (a, b) = (attributes(&run(plan, 1)), attributes(&run(shorter, 2)));
    assert!(a.len() > 500);
    assert_eq!(a, b);

    let by_time = Day {
        attributes: Attributes::Time,
        ..plan
    };
    let shorter = Day {
        day: DAY / 2,
        ..by_time
    };
    assert_ne!(attributes(&run(by_time, 1)), attributes(&run(shorter, 1)));
}
